/**
 * Named aliases for the generated OpenAPI schemas.
 *
 * `schema.d.ts` is regenerated by `npm run gen:api`, so components import these names
 * instead of reaching into `components["schemas"][...]` — if the backend renames a
 * serializer, this file is the only thing that needs fixing.
 */

import type { components } from "./schema";

type Schemas = components["schemas"];

export type Sport = Schemas["Sport"];
export type SportSummary = Schemas["SportSummary"];
export type SportFormat = Schemas["SportFormat"];
export type SportSkill = Schemas["SportSkill"];
export type SportAttributeWeight = Schemas["SportAttributeWeight"];
export type StatDefinition = Schemas["StatDefinition"];
export type SportProposal = Schemas["SportProposal"];
export type Attribute = Schemas["Attribute"];

export type PlayerProfile = Schemas["PlayerProfile"];
export type PublicPlayerProfile = Schemas["PublicPlayerProfile"];
export type PlayerSportCard = Schemas["PlayerSportCard"];
export type PlayerAttributeValue = Schemas["PlayerAttribute"];
export type PlayerSkillValue = Schemas["PlayerSkill"];

export type User = Schemas["User"];

export type Turf = Schemas["TurfSummary"];
export type TurfDetail = Schemas["TurfDetail"];
export type OwnerTurf = Schemas["OwnerTurf"];
export type Ground = Schemas["Ground"];
export type Amenity = Schemas["Amenity"];
export type OperatingHours = Schemas["OperatingHours"];
export type PriceRule = Schemas["PriceRule"];
export type TurfPhoto = Schemas["TurfPhoto"];
export type TurfMembership = Schemas["TurfMembership"];
export type Availability = Schemas["Availability"];
export type Slot = Schemas["Slot"];
export type PriceCoverageGap = Schemas["PriceCoverageGap"];

/**
 * The subset of a profile a {@link PlayerCard} needs.
 *
 * Both `PlayerProfile` (mine) and `PublicPlayerProfile` (someone else's) satisfy it,
 * which is what lets one component serve the profile page, the match board, search
 * results and scorecards.
 */
export type PlayerCardProfile = {
  id: string;
  name: string;
  photo_url: string;
  area?: string;
  bio?: string;
  reliability_score: number;
  attributes: readonly PlayerAttributeValue[];
  sport_cards: readonly PlayerSportCard[];
};
